    # most common = background
    bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    for r in range(H):
        row=g[r]
        other=[c for c in range(W) if row[c]!=bgc]
        if not other or len(other)==W: continue
        line=row[other[0]]
        # check contiguous horizontal line
        if other==list(range(other[0],other[-1]+1)):
            # fill toward nearer edge... fill all background gaps? extend to edge with 1
            # determine side with gap
            left_gap=other[0]>0
            right_gap=other[-1]<W-1
            if left_gap and not right_gap:
                for c in range(0,other[0]): row[c]=1
            elif right_gap and not left_gap:
                for c in range(other[-1]+1,W): row[c]=1
            else:
